import re

from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Adrianna Pienkowska'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'adrianna.pienkowska@nokia.com'


class CellTraceActivate(GenericEMSSIMCommand):
    """Celltraceactivate command class."""

    def __init__(self, connection, interfaces, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Celltraceactivate command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param interfaces: interfaces
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CellTraceActivate, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.interfaces = interfaces
        self.options = options
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'cell_trace_activate -if'
        if self.interfaces:
            cmd = f"{cmd} {','.join(self.interfaces)}"
        if self.options:
            cmd = f'{cmd} {self.options}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_failure(line)
            except ParsingDone:
                pass
        return super(CellTraceActivate, self).on_new_line(line, is_full_line)

    _re_error = re.compile(r"ERROR:(?P<ERROR_MSG>.*)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(CellTraceActivate._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR_MSG')}"))
            raise ParsingDone

    _re_failed = re.compile(r"\*\*\*\s+Cause:(?P<FAILURE_MSG>.*)")

    def _parse_failure(self, line):
        if self._regex_helper.search_compiled(CellTraceActivate._re_failed, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('FAILURE_MSG')}"))
            raise ParsingDone


